import json,shutil # Preserve both failed attempts before applying a physically justified nonlinear repair.
import numpy as np # Resume actual failed displacement states rather than discarding their work.
from nonlinear_mechanics import OUT,FiniteStrain # Reconstruct the unchanged finite-strain elastic potential.
from nonlinear_correct import correct # Use the verified tangent with consistent energy-merit safeguarding.
from fem import write_json # Record every restarted state and the exact extra numerical cost.
def main(): # Repair only states that remain outside the full residual gate after the 25-step attempt.
    records=json.loads((OUT/'correction_results.json').read_text());repairs=[] # Keep already passing independent test states unchanged.
    for receipt in records: # Resume only genuine recorded failures and preserve their raw evidence.
        if receipt['status']=='PASS': continue # Avoid unnecessary recomputation or altered passing evidence.
        identity=receipt['geometry_id'];directory=OUT/'corrected';failure=OUT/'failures';shutil.copy2(directory/f'{identity}.json',failure/f'{identity}_second_correction_failure.json');shutil.copy2(directory/f'{identity}.npz',failure/f'{identity}_second_correction_failure.npz');fields=dict(np.load(directory/f'{identity}.npz'));source=dict(np.load(OUT/'cases'/identity/'trajectory.npz'));adapter=FiniteStrain(source['xyz'],source['tet'],source['groups'],float(source['E']),float(source['nu'])) # Preserve the stagnating force-norm iterate and restore identical physical inputs.
        for j,state in enumerate(receipt['states']): # Use actual recorded physical failure status instead of a surrogate error threshold.
            if state['status']=='PASS': continue # Preserve all completed states and their original costs.
            solution,repaired=correct(adapter,fields['corrected'][j],source['force']*source['load_path'][j],source['free'],source['fixed'],np.linalg.norm(source['force']));fields['corrected'][j]=solution;receipt['states'][j]={'state':j,'load_amplitude':float(source['load_path'][j]),**repaired,'repair':'Restart from the 25-step force-merit iterate; use exact elastic potential Armijo merit plus force-reduction fallback.'};repairs.append({'geometry_id':identity,'state':j,'previous_status':state['status'],'previous_residual':state['final_residual'],'new_status':repaired['status'],'new_residual':repaired['final_residual'],'additional_sparse_newton_solves':repaired['iterations'],'additional_seconds':repaired['seconds'],'evidence':f'build/local-nonlinear-20261024/corrected/{identity}.json'}) # Apply and document only the actual energy-consistent Newton recovery.
        np.savez_compressed(directory/f'{identity}.npz',**fields);receipt['status']='PASS' if all(s['status']=='PASS' for s in receipt['states']) else 'HOLD';receipt['corrected_path_relative_L2']=float(np.linalg.norm(fields['corrected']-fields['truth'])/np.linalg.norm(fields['truth']));receipt['max_corrected_full_residual']=max(s['final_residual'] for s in receipt['states']);receipt['full_sparse_newton_solves']=sum(s['iterations'] for s in receipt['states']);write_json(directory/f'{identity}.json',receipt);print(identity,receipt['status'],receipt['corrected_path_relative_L2'],receipt['max_corrected_full_residual'],flush=True) # Recheck full trajectory acceptance without modifying native labels.
    write_json(OUT/'correction_results.json',records);write_json(OUT/'energy_merit_repair.json',repairs) # Publish final numerical status and the explicit additional repair cost.
if __name__=='__main__': main() # Complete the actual nonlinear stagnation repair and independent verification.
